class VersionInfo:
    def __init__(self, major, minor, patch, prerelease, build):
        self._major = int(major)
        self._minor = int(minor)
        self._patch = int(patch)
        self._prerelease = str(prerelease)
        self._build = str(build)

    def __iter__(self):
        yield self._major
        yield self._minor
        yield self._patch
        yield self._prerelease
        yield self._build

    def __eq__(self, other):
        if isinstance(other, tuple):
            return self._major == other[0] and self._minor == other[1] and self._patch == other[2]
        return False

    def __ne__(self, other):
        return not self.__eq__(other)

    def __lt__(self, other):
        if isinstance(other, tuple):
            return (self._major, self._minor, self._patch) < other
        return False

    def __gt__(self, other):
        return not self.__lt__(other) and not self.__eq__(other)

    def __le__(self, other):
        return self.__lt__(other) or self.__eq__(other)

    def __ge__(self, other):
        return self.__gt__(other) or self.__eq__(other)

    def bump_major(self):
        return VersionInfo(self._major + 1, 0, 0, '', '')

    def bump_minor(self):
        return VersionInfo(self._major, self._minor + 1, 0, '', '')

    def bump_patch(self):
        return VersionInfo(self._major, self._minor, self._patch + 1, '', '')

    def bump_prerelease(self):
        return VersionInfo(self._major, self._minor, self._patch, '1', '')

    def bump_build(self):
        return VersionInfo(self._major, self._minor, self._patch, '', '1')

    def replace(self, **kwargs):
        new_version = VersionInfo(self._major, self._minor, self._patch, self._prerelease, self._build)
        for key, value in kwargs.items():
            if key in ['major', 'minor', 'patch', 'prerelease', 'build']:
                if key == 'major':
                    new_version = VersionInfo(value, new_version._minor, new_version._patch, new_version._prerelease, new_version._build)
                elif key == 'minor':
                    new_version = VersionInfo(new_version._major, value, new_version._patch, new_version._prerelease, new_version._build)
                elif key == 'patch':
                    new_version = VersionInfo(new_version._major, new_version._minor, value, new_version._prerelease, new_version._build)
                elif key == 'prerelease':
                    new_version = VersionInfo(new_version._major, new_version._minor, new_version._patch, str(value), new_version._build)
                elif key == 'build':
                    new_version = VersionInfo(new_version._major, new_version._minor, new_version._patch, new_version._prerelease, str(value))
        return new_version

